                + " monitor_round = monitor_round + 1, round_success = 0, round_failed = 0,"
                + " updated_at = CURRENT_TIMESTAMP"
                + " WHERE id = ? AND version = ? AND status = 'PAUSED'", id, expectedVersion);
    }
