        // 重复申请恢复：409
        mockMvc.perform(post("/api/freezes/" + second + "/resume-requests").contentType("application/json")
                        .content("{\"requestId\":\"r-rr3\",\"operator\":\"alice\",\"reason\":\"再次申请\"}"))
